        head = (head + 1) % cap;
        return true;
    }

    int Front()  { return isEmpty() ? -1 : buf[head]; }
    int Rear()   { return isEmpty() ? -1 : buf[(tail - 1 + cap) % cap]; }
    bool isEmpty(){ return head == tail; }
    bool isFull() { return (tail + 1) % cap == head; }
